export const CARD_PRINTINGS: CardPrinting[] = [
  ...CARDS_SV_151_EN,
  ...CARDS_SV_PRE_EN,
  ...CARDS_SV_151_JP,
  ...CARDS_SWSH_CRZ_EN,
  ...CARDS_POCKET_A1_EN,
  ...CARDS_MEG_30TH_EN,
];

export function resolveCardCdnUrl(card: CardPrinting): string {
  if (card.setId === 'sv-151-en') {
    if (card.setNumber === 'E01') return 'https://images.pokemontcg.io/sve/1_hires.png';
    if (card.setNumber === 'E02') return 'https://images.pokemontcg.io/sve/2_hires.png';
    if (card.setNumber === 'E03') return 'https://images.pokemontcg.io/sve/3_hires.png';
    if (card.setNumber === 'E04') return 'https://images.pokemontcg.io/sve/4_hires.png';
    if (card.setNumber === 'E05') return 'https://images.pokemontcg.io/sve/5_hires.png';
    return `https://assets.tcgdex.net/en/sv/sv03.5/${card.setNumber}/high.webp`;
  }

  if (card.setId === 'sv-151-jp') {
    return `https://assets.tcgdex.net/ja/SV/SV2a/${card.setNumber}/high.webp`;
  }

  if (card.setId === 'swsh-crz-en') {
    return `https://assets.tcgdex.net/en/swsh/swsh12.5/${card.setNumber}/high.webp`;
  }

  if (card.setId === 'sv-pre-en') {
    return `https://assets.tcgdex.net/en/sv/sv08.5/${card.setNumber}/high.webp`;
  }

  if (card.setId === 'pocket-a1-en') {
    return `https://assets.tcgdex.net/en/tcgp/A1/${card.setNumber}/high.webp`;
  }

  if (card.setId === 'meg-30th-en') {
    // RGB Mew Trio by YOSHIROTTEN
    if (card.id === 'meg-30th-rgb-r' || card.id === 'meg-30th-rgb-g' || card.id === 'meg-30th-rgb-b') {
      return 'https://images.pokemontcg.io/cel25/25_hires.png';
    }

    // Energies E01 - E08
    if (card.setNumber === 'E01') return 'https://images.pokemontcg.io/sve/1_hires.png';
    if (card.setNumber === 'E02') return 'https://images.pokemontcg.io/sve/2_hires.png';
    if (card.setNumber === 'E03') return 'https://images.pokemontcg.io/sve/3_hires.png';
    if (card.setNumber === 'E04') return 'https://images.pokemontcg.io/sve/4_hires.png';
    if (card.setNumber === 'E05') return 'https://images.pokemontcg.io/sve/5_hires.png';
    if (card.setNumber === 'E06') return 'https://images.pokemontcg.io/sve/6_hires.png';
    if (card.setNumber === 'E07') return 'https://images.pokemontcg.io/sve/7_hires.png';
    if (card.setNumber === 'E08') return 'https://images.pokemontcg.io/sve/8_hires.png';

    // Classic Collection C01 - C30
    if (card.setNumber === 'C01') return 'https://images.pokemontcg.io/cel25c/4_hires.png';
    if (card.setNumber === 'C02') return 'https://images.pokemontcg.io/cel25c/2_hires.png';
    if (card.setNumber === 'C03') return 'https://images.pokemontcg.io/cel25c/15_hires.png';
    if (card.setNumber === 'C04') return 'https://images.pokemontcg.io/cel25c/17_hires.png';
    if (card.setNumber === 'C05') return 'https://images.pokemontcg.io/cel25c/66_hires.png';
    if (card.setNumber === 'C06') return 'https://images.pokemontcg.io/cel25c/9_hires.png';
    if (card.setNumber === 'C07') return 'https://assets.tcgdex.net/en/xy/xy6/76/high.webp';
    if (card.setNumber === 'C08') return 'https://images.pokemontcg.io/cel25c/15_hires.png';
    if (card.setNumber === 'C09') return 'https://images.pokemontcg.io/cel25/24_hires.png';
    if (card.setNumber === 'C10') return 'https://images.pokemontcg.io/cel25c/60_hires.png';

    // Pikachu Variants (001 - 030)
    if (card.id === 'meg-30th-001') return 'https://images.pokemontcg.io/cel25/5_hires.png';
    if (card.id === 'meg-30th-002') return 'https://images.pokemontcg.io/cel25/6_hires.png';
    if (card.id === 'meg-30th-003') return 'https://images.pokemontcg.io/cel25/7_hires.png';
    if (card.id === 'meg-30th-004') return 'https://images.pokemontcg.io/cel25/8_hires.png';
    if (card.id === 'meg-30th-005') return 'https://images.pokemontcg.io/cel25/9_hires.png';
    if (card.id === 'meg-30th-006') return 'https://images.pokemontcg.io/cel25/24_hires.png';
    if (card.id === 'meg-30th-007') return 'https://assets.tcgdex.net/en/xy/g1/12/high.webp';
    if (card.id === 'meg-30th-008') return 'https://assets.tcgdex.net/en/xy/xy6/76/high.webp';

    // Gold Rarities
    if (card.setNumber === '156') return 'https://images.pokemontcg.io/cel25/5_hires.png';
    if (card.setNumber === '157') return 'https://images.pokemontcg.io/cel25/7_hires.png';
    if (card.setNumber === '158') return 'https://images.pokemontcg.io/cel25/25_hires.png';

    return 'https://assets.tcgdex.net/en/swsh/cel25/22/high.webp';
  }

  return '';
}

export function resolveCardImageUrl(card: CardPrinting): string {
  if (card.imageUrl) return card.imageUrl;

  const cdn = resolveCardCdnUrl(card);
  if (cdn) return cdn;

  // Local assets are 100% offline & zero network latency
  if (card.setNumber === 'E01') return '/assets/cards/energy-grass.png';
  if (card.setNumber === 'E02') return '/assets/cards/energy-fire.png';
  if (card.setNumber === 'E03') return '/assets/cards/energy-water.png';
  if (card.setNumber === 'E04') return '/assets/cards/energy-lightning.png';
  if (card.setNumber === 'E05') return '/assets/cards/energy-psychic.png';

  if (card.id === 'meg-30th-001') return '/assets/cards/meg-30th-001.png';
  if (card.id === 'meg-30th-025') return '/assets/cards/meg-30th-025.png';

  return `/assets/cards/${card.id.toLowerCase()}.webp`;
}

// Ensure all card objects have their authentic image URLs
CARD_PRINTINGS.forEach((c) => {
  if (!c.imageUrl) {
    c.imageUrl = resolveCardImageUrl(c);
  }
});

export const CARDS_MAP = new Map(CARD_PRINTINGS.map((c) => [c.id, c]));
